import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Return Custom Fields","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/return-custom-fields/index.md","filePath":"api/graphql-api/admin/settings/return-custom-fields/index.md","lastUpdated":1787290888000}'),r={name:"api/graphql-api/admin/settings/return-custom-fields/index.md"};function s(i,t,c,n,l,u){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="return-custom-fields" tabindex="-1">Return Custom Fields <a class="header-anchor" href="#return-custom-fields" aria-label="Permalink to &quot;Return Custom Fields&quot;">​</a></h1><p>The <strong>Return Custom Fields</strong> menu is part of the store&#39;s <strong>RMA (Returns) settings</strong>. Extra fields the return form collects from the customer (for example a preferred-resolution dropdown). Each field has a <code>code</code>, <code>label</code>, input <code>type</code>, required flag, position and — for <code>select</code> / <code>multiselect</code> / <code>checkbox</code> / <code>radio</code> types — a list of <code>options</code>.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./queries/list.html">List</a></td><td><code>adminRmaCustomFields</code> query</td></tr><tr><td><a href="./queries/get.html">Get</a></td><td><code>adminRmaCustomField(id:)</code> query</td></tr><tr><td><a href="./mutations/create.html">Create</a></td><td><code>createAdminRmaCustomField</code> mutation</td></tr><tr><td><a href="./mutations/update.html">Update</a></td><td><code>updateAdminRmaCustomField</code> mutation</td></tr><tr><td><a href="./mutations/delete.html">Delete</a></td><td><code>deleteAdminRmaCustomField</code> mutation</td></tr><tr><td><a href="./mutations/mass-delete.html">Mass delete</a></td><td><code>createAdminRmaCustomFieldMassDelete</code> mutation</td></tr><tr><td><a href="./mutations/mass-update-status.html">Mass update status</a></td><td><code>createAdminRmaCustomFieldMassUpdateStatus</code> mutation</td></tr></tbody></table><p>List queries are cursor-paginated Relay connections.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>Unique machine code for the field.</td></tr><tr><td><code>label</code></td><td>The field label shown to the customer.</td></tr><tr><td><code>type</code></td><td>Input type: <code>text</code>, <code>textarea</code>, <code>select</code>, <code>multiselect</code>, <code>checkbox</code>, <code>radio</code>.</td></tr><tr><td><code>isRequired</code></td><td><code>1</code> if the customer must fill it in, <code>0</code> otherwise.</td></tr><tr><td><code>position</code></td><td>Sort order in the returns form.</td></tr><tr><td><code>inputValidation</code></td><td>Optional validation rule name; <code>null</code> when none.</td></tr><tr><td><code>status</code></td><td><code>1</code> active, <code>0</code> inactive.</td></tr><tr><td><code>options</code></td><td>Choice list for <code>select</code> / <code>multiselect</code> / <code>checkbox</code> / <code>radio</code> types — an array of <code>{ id, name, value }</code>. Empty/absent for <code>text</code> / <code>textarea</code>.</td></tr><tr><td><code>message</code></td><td><code>null</code> on create / update / read; populated only on the delete confirmation.</td></tr></tbody></table><p>Select <code>_id</code> for the numeric id; <code>id</code> is the resource IRI.</p><h2 id="how-rma-settings-fit-together" tabindex="-1">How RMA settings fit together <a class="header-anchor" href="#how-rma-settings-fit-together" aria-label="Permalink to &quot;How RMA settings fit together&quot;">​</a></h2><p>Reasons, statuses and custom fields shape the <strong>returns form</strong> the customer fills in when opening a return; <strong>rules</strong> set the <strong>return window</strong> that decides whether a product is still eligible. Together they make up the store&#39;s RMA (Returns) settings.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th></tr></thead><tbody><tr><td>Create</td><td><code>sales.rma.custom-fields.create</code></td></tr><tr><td>Update / mass update status</td><td><code>sales.rma.custom-fields.edit</code></td></tr><tr><td>Delete / mass delete</td><td><code>sales.rma.custom-fields.delete</code></td></tr></tbody></table>',12)]))}const p=e(r,[["render",s]]);export{h as __pageData,p as default};
